from __future__ import annotations

import asyncio
import json
import socket
from pathlib import Path
from typing import Any, AsyncIterator


class HostControlError(RuntimeError):
    pass


class HostControlClient:
    """Client for the restricted host systemd proxy used by Docker deployments."""

    def __init__(self, socket_path: str) -> None:
        self.socket_path = str(Path(socket_path))

    def request(self, payload: dict[str, Any], timeout: float = 20.0) -> dict[str, Any]:
        encoded = (json.dumps(payload, separators=(",", ":")) + "\n").encode()
        try:
            with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as connection:
                connection.settimeout(timeout)
                connection.connect(self.socket_path)
                connection.sendall(encoded)
                response = self._read_line(connection)
        except (OSError, TimeoutError) as exc:
            raise HostControlError(
                f"Host control socket unavailable ({self.socket_path}): {exc}"
            ) from exc

        try:
            result = json.loads(response)
        except json.JSONDecodeError as exc:
            raise HostControlError("Invalid response from host control service") from exc
        if not result.get("ok", False):
            raise HostControlError(result.get("error", "Host control operation failed"))
        return result

    def systemctl(
        self,
        action: str,
        service: str,
        properties: list[str] | None = None,
        timeout: float = 20.0,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "op": "systemctl",
            "action": action,
            "service": service,
        }
        if properties:
            payload["properties"] = properties
        return self.request(payload, timeout=timeout)

    def journal(
        self,
        service: str | None,
        lines: int,
        priority: str | None = None,
        timeout: float = 20.0,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "op": "journal",
            "service": service,
            "lines": lines,
            "follow": False,
        }
        if priority:
            payload["priority"] = priority
        return self.request(payload, timeout=timeout)

    def permissions(self) -> dict[str, Any]:
        return self.request({"op": "permissions"}, timeout=5.0)

    async def follow_journal(self, service: str, lines: int = 50) -> AsyncIterator[str]:
        try:
            reader, writer = await asyncio.open_unix_connection(self.socket_path)
        except OSError as exc:
            raise HostControlError(
                f"Host control socket unavailable ({self.socket_path}): {exc}"
            ) from exc

        request = {
            "op": "journal",
            "service": service,
            "lines": lines,
            "follow": True,
        }
        writer.write((json.dumps(request, separators=(",", ":")) + "\n").encode())
        await writer.drain()
        try:
            while True:
                encoded = await reader.readline()
                if not encoded:
                    break
                message = json.loads(encoded)
                if not message.get("ok", False):
                    raise HostControlError(message.get("error", "Host log stream failed"))
                if message.get("type") == "eof":
                    break
                if message.get("type") == "line":
                    yield str(message.get("line", ""))
        finally:
            writer.close()
            try:
                await writer.wait_closed()
            except (BrokenPipeError, ConnectionResetError):
                pass

    @staticmethod
    def _read_line(connection: socket.socket, limit: int = 4 * 1024 * 1024) -> str:
        chunks = bytearray()
        while len(chunks) < limit:
            chunk = connection.recv(min(65536, limit - len(chunks)))
            if not chunk:
                break
            chunks.extend(chunk)
            newline = chunks.find(b"\n")
            if newline >= 0:
                return chunks[:newline].decode("utf-8")
        if len(chunks) >= limit:
            raise HostControlError("Host control response exceeds size limit")
        if not chunks:
            raise HostControlError("Host control service returned no response")
        return chunks.decode("utf-8")
